static void test_mul(void) {
    TEST_SUITE("p256_scalar_mul — a * b mod n");
    for (int i = 0; i < NSCPAIRS; i++) {
        uint64_t a[4], b[4], out[4];
        uint8_t outb[32];
        p256_fe_frombytes(a, SCPAIRS[i].a);
        p256_fe_frombytes(b, SCPAIRS[i].b);
        p256_scalar_mul(out, a, b);
        p256_fe_tobytes(outb, out);
        ASSERT_EQ("a*b mod n", 0, memcmp(outb, SCPAIRS[i].prod, 32));
    }
}

int main(void) {
    test_mul();
    test_summary();
    return 0;
}
